const contactos = $input.all();

const autorizado =
  contactos.length === 1 &&
  !!contactos[0].json.id &&
  Array.isArray(contactos[0].json.fields?.Empresa) &&
  contactos[0].json.fields.Empresa.length === 1;

return [{
  json: {
    autorizado: autorizado,
    contacto_record_id: autorizado ? contactos[0].json.id : null,
    nombre_contacto: autorizado ? contactos[0].json.fields.Nombre : null,
    empresa_record_id: autorizado ? contactos[0].json.fields.Empresa[0] : null
  }
}];

